import{_ as e,o as a,c as o,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"网络优化（Network）：适用问题与学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/network/index.md","filePath":"zh-cn/frameworks/network/index.md"}'),d={name:"zh-cn/frameworks/network/index.md"};function l(i,t,n,c,h,s){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="网络优化-network-适用问题与学习路线" tabindex="-1">网络优化（Network）：适用问题与学习路线 <a class="header-anchor" href="#网络优化-network-适用问题与学习路线" aria-label="Permalink to &quot;网络优化（Network）：适用问题与学习路线&quot;">​</a></h1><p>在有向网络中满足供需，遵守运输或处理容量，并最小化费用。之后可以增加网络建设、资源路径、网络结构与故障场景。节点表示供给点、需求点或中转点；连接两个节点的有向服务称为“弧”。车辆路径只是 Network 的一种应用。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>角色</th><th>核心字段</th></tr></thead><tbody><tr><td>拓扑</td><td>Node / Arc</td><td>输入</td><td>稳定身份、端点和平行服务</td></tr><tr><td>商品与供需</td><td>Commodity / Balance</td><td>输入</td><td>各商品的节点供需与计量单位</td></tr><tr><td>容量和费用</td><td>Capacity / Cost</td><td>输入</td><td>弧及共享资源的上限、单价</td></tr><tr><td>流问题</td><td><code>FlowProblem</code></td><td>输入</td><td>拓扑、商品、费用与资源配置</td></tr><tr><td>注册与提取</td><td><code>FlowContext</code></td><td>调用 / 校验入口</td><td>守恒、容量、费用表达式和流量结果</td></tr><tr><td>流量结果</td><td><code>FlowSolution</code></td><td>输出</td><td>商品-弧流量、资源占用、未使用供应、缺货与费用</td></tr></tbody></table><p>整数步长表示计量粒度，不表示整单不可拆。不同商品共同占用资源时，需要明确物理量换算，不能把吨和件直接相加。</p><div class="tip custom-block"><p class="custom-block-title">商品可用弧的空值</p><p><code>allowedArcs = null</code> / <code>allowed_arcs = None</code> 表示允许全部服务弧，空集合则不允许任何服务弧。供需与共享容量均保留单位；整数步长只定义计量粒度。</p></div><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin 与 Rust 的入口差异</p><p>独立流入口为 Kotlin <code>NetworkFlowApplicationService</code>、Rust <code>FlowApplicationService</code>。嵌入其他模型时使用 <code>FlowContext</code> 注册，不要再启动一个不共享变量的独立优化。</p></div><p>先学习流与容量，再扩展网络建设和故障场景下的供需保障。带时间窗的车辆路径（VRPTW）及其列生成算法属于进阶内容，算法名称见<a href="./../#terminology">术语说明</a>。</p><p>纯流与共享容量直接使用独立流服务；增加联合决策时改为共同模型注册，而不是切换到不存在的 <code>NetworkColumnGeneration</code>。车辆路线列生成属于另一个进阶流程，当前流问题的后端预算与列数无关。见<a href="./business-scenario.html#entry-budget">调用代码</a>。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>平行弧需要独立身份，不能只按起点/终点去重。</li><li>连通性不证明运输容量充足；建成总容量不等于增量容量。</li><li>故障模型只检查明确列出的场景，不能由此保证任意未知故障下仍可满足需求。</li><li>维修作业的时间、人员和日历属于 <a href="./../gantt/">Gantt</a>，不是 Network 自动决定的。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-flow.html">第一次网络流优化</a>，先检查守恒、费用与容量。</li><li>增加共享资源、容量等级、建设预算和一个故障场景，每次只改一类条件。</li><li>需要车辆路线时，继续到 <a href="/ospf/zh-cn/examples/framework-example5.html">VRPTW 综合案例</a>。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-network-scheduling/README_ch.md" target="_blank" rel="noreferrer">Kotlin 网络领域与独立入口</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-network-scheduling/README_ch.md" target="_blank" rel="noreferrer">Rust 网络领域与求解结果说明</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./first-flow.html">第一次网络流优化</a>。完成后再学<a href="./business-scenario.html">共享资源、缺货与联合模型</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',19)])])}const p=e(d,[["render",l]]);export{f as __pageData,p as default};
